import{_ as a}from"./chunks/settings-cards.DefgbiKb.js";import{_ as e,o as d,c as r,a2 as s}from"./chunks/framework.BqDA2HS7.js";const m=JSON.parse('{"title":"规划路由","description":"","frontmatter":{},"headers":[],"relativePath":"planning.md","filePath":"planning.md"}'),o={name:"planning.md"};function i(l,t,n,h,c,g){return d(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="规划路由" tabindex="-1">规划路由 <a class="header-anchor" href="#规划路由" aria-label="Permalink to &quot;规划路由&quot;">​</a></h1><p>规划路由保留接入方 Agent 的原生执行循环。模型回复、工具调用与结果配对、实际来源和 已接受历史随请求保留；Router 负责策略、模型准入、Judge 和受管模型费用。</p><h2 id="六种策略" tabindex="-1">六种策略 <a class="header-anchor" href="#六种策略" aria-label="Permalink to &quot;六种策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>决策边界</th><th>执行器的变化</th></tr></thead><tbody><tr><td>Static</td><td>新任务选一次</td><td>固定角色，或按权重随机一次并保持</td></tr><tr><td>Stage</td><td>新的可信工具证据</td><td>高效起步、困难时临时接管、保持后可恢复</td></tr><tr><td>Task</td><td>新任务开始</td><td>从自选模型池选择主模型，任务内保持</td></tr><tr><td>Composite</td><td>Task 初选 + 后续 Stage</td><td>常用模型与指定接管模型之间切换</td></tr><tr><td>Advisor Gate</td><td>最终候选边界</td><td>固定执行器，最多一次返工并复审</td></tr><tr><td>Escalation</td><td>起始模型的未交付候选</td><td>一次接管后固定使用接管模型</td></tr></tbody></table><p>具体行为见<a href="./strategies/">策略概览</a>。</p><h2 id="在-dsh-中设置" tabindex="-1">在 DSH 中设置 <a class="header-anchor" href="#在-dsh-中设置" aria-label="Permalink to &quot;在 DSH 中设置&quot;">​</a></h2><p>设置位于独立的 <strong>RefractAgent 规划路由</strong> 卡片，不与自动路由的 DAG 配置混放。</p><ol><li>配置共用模型资料、预算和数据域。</li><li>选择正在编辑的策略，填写该策略真正需要的模型与 Judge。</li><li>核对价格与能力诊断，运行零调用检查。</li><li>保存后，在对话模型菜单的“路由模式”中选择。</li></ol><p>“正在编辑的策略”不等于“默认路由策略”。保存设置从下个任务生效；正在运行的任务使用 已冻结配置。默认策略不应强行覆盖会话已经选择的模式。</p><h2 id="界面与设置" tabindex="-1">界面与设置 <a class="header-anchor" href="#界面与设置" aria-label="Permalink to &quot;界面与设置&quot;">​</a></h2><p>规划路由的设置位于 DSH 设置窗口的 <strong>插件</strong> 区域，与自动路由各自独立卡片：</p><figure class="doc-screenshot"><a href="/screenshots/dsh-20261014/settings-cards.png" target="_blank" rel="noopener"><img src="'+a+'" alt="实际插件设置页中的两个 RefractAgent 路由卡片"></a><figcaption>2026-10-14 实际 DSH 设置窗口：分别展开规划路由与自动路由。</figcaption></figure><p>展开 <strong>RefractAgent 规划路由</strong> 卡片后，按正在编辑的策略配置模型角色、Judge、预算与数据域， 运行零调用检查后保存。在对话输入框的模型菜单中选择“路由模式”即可使用。</p><p>六个策略页面都提供本轮实际设置截图、字段解释、流程图及案例： <a href="./strategies/static.html">Static</a>、<a href="./strategies/stage.html">Stage</a>、<a href="./strategies/task.html">Task</a>、 <a href="./strategies/composite.html">Composite</a>、<a href="./strategies/advisor.html">Advisor</a>、 <a href="./strategies/escalation.html">Escalation</a>。截图由 Playwright 打开实际 DSH 页面并滚动捕获， 使用已安装插件 <code>0.33.25</code>；仓库下载包为 <code>0.33.21</code>，版本区别见<a href="./routing.html">入口说明</a>。</p><p>截图中“默认路由策略”始终保持 Stage，只切换“正在编辑的策略”来查看字段，未保存配置。 例如在 Task 页看见上方 Stage、下方 Task，表示正在编辑 Task；不能据此说当前任务已经使用 Task。</p><h3 id="一个工具任务如何经过规划路由" tabindex="-1">一个工具任务如何经过规划路由 <a class="header-anchor" href="#一个工具任务如何经过规划路由" aria-label="Permalink to &quot;一个工具任务如何经过规划路由&quot;">​</a></h3><p>以“调用一次终端工具执行 <code>printf %s STAGE_01_OK</code>，读取 stdout 后只回复该标记”为例：</p><ol><li>DSH 把用户要求与可用工具传给 Python 核心；Stage 首轮没有工具证据，选择高效执行器。</li><li>执行器产生工具请求，DSH 按自己的权限规则执行终端命令并保存回执。</li><li>DSH 携带已接受历史、工具请求和匹配结果续接；核心消费新增证据，选择下一轮模型。</li><li>执行器回复标记，费用按真实模型调用结算；该任务没有拆成 DAG。</li></ol><p>换成 Composite 时，在第 1 步之前多一次 Task 初选；换成 Advisor 时，在最终文字交付前 增加审核 Gate。工具的执行方与权限方仍是 DSH。</p><h2 id="六策略真实运行案例" tabindex="-1">六策略真实运行案例 <a class="header-anchor" href="#六策略真实运行案例" aria-label="Permalink to &quot;六策略真实运行案例&quot;">​</a></h2><p>下表来自 2026-09-29 的 128 项正式验收（<code>reports/dsh-strategy-stability-20260929-v3</code>）， 每个策略抽取第一个任务作为示例。模型为 <code>deepseek-v4-flash</code>（DSF）、 <code>deepseek-v4.1-flash</code>（V4.1）与 <code>glm-5.3-flash</code>（GLM）。</p><table tabindex="0"><thead><tr><th>策略</th><th>调用序列</th><th>决策原因</th><th>费用（AFP）</th><th>首字</th><th>总延迟</th></tr></thead><tbody><tr><td>Static</td><td>V4.1</td><td>static-random-selected</td><td>3.116</td><td>1.79s</td><td>1.80s</td></tr><tr><td>Stage</td><td>DSF → DSF</td><td>no-signal → ambiguous</td><td>1.254</td><td>1.24s</td><td>4.38s</td></tr><tr><td>Task</td><td>GLM(判) → DSF</td><td>task-llm-judge → quality-then-first-call-cost</td><td>0.774</td><td>3.13s</td><td>5.60s</td></tr><tr><td>Composite</td><td>GLM(判) → DSF → DSF</td><td>task-llm-judge → selected → ambiguous-base</td><td>1.408</td><td>3.21s</td><td>7.66s</td></tr><tr><td>Advisor</td><td>V4.1 → DSF(审)</td><td>advisor-initial → advisor-approved</td><td>3.670</td><td>1.41s</td><td>4.50s</td></tr><tr><td>Escalation</td><td>DSF → GLM(审)</td><td>escalation-initial → escalation-proceed</td><td>1.170</td><td>2.33s</td><td>4.75s</td></tr></tbody></table><p>几个值得注意的行为：</p><ul><li><strong>Static</strong> 的冻结随机在两条执行路线间抽取，同一批次 12 项任务同时覆盖了 DSF 与 V4.1。</li><li><strong>Stage</strong> 第一轮无信号用高效模型，工具回执 ambiguous 后保持同一模型；同批次 24 项 每项恰好一次宿主工具调用。</li><li><strong>Task</strong> 的 Judge（GLM）只调用一次完成分类，之后固定选择质量达标且首调用成本更低的 DSF。</li><li><strong>Composite</strong> 比 Task 多一次执行调用：Task 选出常用模型后，后续轮次由 Stage 规则 判断是否需要临时接管。</li><li><strong>Advisor</strong> 的执行与审核分开计费（V4.1 执行 + DSF 审核），候选经审核批准后才交付。</li><li><strong>Escalation</strong> 的 Judge 检查起始候选后放行（PROCEED），同批次 24 项全部一次通过， 未触发接管。</li></ul><p>这些是当时插件 <code>0.29.0</code>、核心 <code>0.15.4</code> 的受控文本／工具案例，Judge 使用冻结的 LLM 配置，与本轮部分截图中的官方 Jev 配置分开看。AFP 使用历史订阅口径，不能折算成 CNY。 128 项成功证明对应路径可完成，不证明六策略在开放任务上普遍优于 Static。 完整任务、模型分布与失败批次见 <a href="https://github.com/AEALab/RefractRouter/blob/main/reports/dsh-strategy-stability-20260929-v3/README.md" target="_blank" rel="noreferrer">验收报告</a>、 <a href="https://github.com/AEALab/RefractRouter/blob/main/reports/dsh-strategy-stability-20260929-v3/records.jsonl" target="_blank" rel="noreferrer">逐任务记录</a>。</p><h2 id="新任务与续接" tabindex="-1">新任务与续接 <a class="header-anchor" href="#新任务与续接" aria-label="Permalink to &quot;新任务与续接&quot;">​</a></h2><p>新用户轮次建立新任务状态。工具续接、进行中的追加指导和宿主压缩沿用当前状态， 不重新取得预算、不重复 Task 分类、不清零审核或升级计数。</p><p>标准模型接口需要可靠关联任务身份与历史。不能把首条消息的 hash 当成通用真实任务 ID； 身份无法确定的接入方式按其支持边界限制，不猜测兼容。</p><h2 id="输出与取消" tabindex="-1">输出与取消 <a class="header-anchor" href="#输出与取消" aria-label="Permalink to &quot;输出与取消&quot;">​</a></h2><p>Static、Stage、Task、Composite 在选模后允许正常流式文本。 Advisor 和 Escalation 的待判别候选需要缓冲；未接受的文本与工具调用不会交付。 已经释放的文本不能被策略悄悄替换。接管后的 Escalation 可以流式输出，并注明未追加审核。</p><p>取消释放未派发的保护额度；已经派发的调用继续结算或保留待核对预留。 模型用量未知、认证／传输故障、账本或证据写入失败时停止后续受管调用。</p><h2 id="配置可执行不等于质量已通过" tabindex="-1">配置可执行不等于质量已通过 <a class="header-anchor" href="#配置可执行不等于质量已通过" aria-label="Permalink to &quot;配置可执行不等于质量已通过&quot;">​</a></h2><p>零调用诊断核对模型、能力、价格、预算、信任和接口要求，不评价实际任务质量。 Judge 是辅助信号，最终仍需要你的验收条件。所有失败尝试、判别和被丢弃回复均需计入费用。</p>',33)])])}const b=e(o,[["render",i]]);export{m as __pageData,b as default};
